(341, 'default', 'created', 41, 'App\\Project', 556, 'App\\User', '{\"attributes\":{\"user_id\":556,\"name\":\"Hochzeit Vintage 2\",\"projektname\":\"1601630341\",\"cat_id\":18,\"cat_name\":\"Fotografie | Soloportrait\",\"group\":6,\"beschreibung\":null,\"youtube\":\"\",\"copyright\":\"Fotostudio Semrad\",\"testimonial\":null,\"check\":1,\"ort\":\"Concordia Schl\\u00f6ssl Wien\",\"stat\":0,\"deleted_at\":null,\"extra\":\"4. November 2016\",\"jury\":0}}', '2020-10-02 09:19:01', '2020-10-02 09:19:01'),
