INSERT INTO `activity_log` (`id`, `log_name`, `description`, `subject_id`, `subject_type`, `causer_id`, `causer_type`, `properties`, `created_at`, `updated_at`) VALUES
(1912, 'default', 'updated', 156, 'App\\Project', 437, 'App\\User', '{\"attributes\":{\"user_id\":437,\"name\":\"Huber zu Laah \\u2013 der Hochzeitshof \\u2026 the place where love & magic happens\",\"projektname\":\"1604066559\",\"cat_id\":23,\"cat_name\":\"Location f\\u00fcr Trauungszeremonien\",\"group\":9,\"beschreibung\":\"Ein Ort, eingebettet in die wundersch\\u00f6ne idyllische Landschaft Ober\\u00f6sterreichs und zentral zwischen den St\\u00e4dten Linz und Steyr gelegen.\\r\\n\\r\\nEin Hof der unz\\u00e4hligen M\\u00f6glichkeiten bietet \\u2013 Trends, Nachhaltigkeit, Flexibilit\\u00e4t und Individualit\\u00e4t werden hier gro\\u00dfgeschrieben.\\r\\n\\r\\nDer Hochzeit eine ganz pers\\u00f6nliche Note zu verpassen, diesen Tag so zu gestalten und zu erleben, wie man es sich bereits in Tr\\u00e4umen ausgemalt hat \\u2013 das ist es, so soll es sein und dieser Zauber soll durch nichts verfliegen\\u2026 \\r\\nHarmony and good vibes all around - vom ersten Moment bis hin zum gro\\u00dfen Tag.\\r\\n\\r\\nDas sind wir, daf\\u00fcr stehen wir!\\r\\n\\r\\nWir erm\\u00f6glichen es, diesen Traum \\\"HOCHZEIT\\\" wahr werden zu lassen. \\r\\n\\r\\nHuber zu Laah,\\r\\n...einzigartig, auch \\u00fcber die Grenzen \\u00d6sterreichs hinaus, grenzt eine wundersch\\u00f6ne Kirche die direkt an den Hausmauern des Vierkanthofes,\\r\\n...ein Festgarten, in dem sich Brautpaare unter dem schattenspendenden Baum das \\u201eJa-Wort\\u201c geben k\\u00f6nnen, \\r\\nein historisches Gew\\u00f6lbe, das 100 Jahre unter der Erde versch\\u00fcttet war und wieder freigelegt wurde f\\u00fcr intime Trauungen zu zweit, \\r\\n...eine rustikale Scheune als Trauungsort, f\\u00fcr all die, die lockere Boho-Vibes lieben,\\r\\n...oder die Trauung im Wald f\\u00fcr Naturverbundene, die am liebsten barfu\\u00df den moosbedecken Boden unter ihrem F\\u00fc\\u00dfen sp\\u00fcren.\\r\\nIn diesem herausfordernden Jahr 2020 auch erstmalig unser Festsaal als Trauungsort - nat\\u00fcrlich mit Einhaltung aller zum Zeitpunkt geltenden Regelungen - because love ist not cancelled!\\r\\n\\r\\nUnsere Mission ist es, jede einzelne Hochzeit zu einem ganz besonderen Fest zu machen, deshalb k\\u00fcmmern wir uns um jedes noch so kleine Detail mit Hingabe und Leidenschaft.\\r\\n\\r\\nSo individuell und vielseitig wie all die Herzen da drau\\u00dfen, das sind wir \\r\\n\\r\\nHuber zu Laah\\r\\n\\r\\n\\u201elet your beautiful soul sparkle and shine\\u201c.\",\"youtube\":\"\",\"copyright\":\"Hannah & Rene, Kati Fine Art\",\"testimonial\":null,\"check\":1,\"ort\":\"Maria Laah, Huber zu Laah\",\"datum\":\"2019_2020\",\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0},\"old\":{\"user_id\":437,\"name\":\"Huber zu Laah \\u2013 der Hochzeitshof \\u2026 the place where love & magic happens\",\"projektname\":\"1604066559\",\"cat_id\":23,\"cat_name\":\"Location f\\u00fcr Trauungszeremonien\",\"group\":9,\"beschreibung\":\"Ein Ort, eingebettet in der wundersch\\u00f6nen idyllischen Landschaft Ober\\u00f6sterreichs, \\r\\ndennoch zentral zwischen den St\\u00e4dten Linz und Steyr gelegen.\\r\\n\\r\\nEin Hof der unz\\u00e4hligen M\\u00f6glichkeiten bietet \\u2013 Trends, Nachhaltigkeit, Flexibilit\\u00e4t und Individualit\\u00e4t wird hier gro\\u00dfgeschrieben.\\r\\n\\r\\nDer Hochzeit eine ganz pers\\u00f6nliche Note zu verpassen, diesen Tag so zu gestalten und zu erleben, wie man es sich bereits in Tr\\u00e4umen ausgemalt hat \\u2013 das ist es, so soll es sein und dieser Zauber soll durch nichts verfliegen\\u2026 \\r\\nHarmony and good vibes all around - vom ersten Moment bis hin zum gro\\u00dfen Tag.\\r\\n\\r\\nDas sind wir, daf\\u00fcr stehen wir!\\r\\n\\r\\nWir erm\\u00f6glichen es, diesen Traum HOCHZEIT wahr werden zu lassen. \\r\\n\\r\\nEinzigartig, auch \\u00fcber die Grenzen \\u00d6sterreichs hinaus, durch eine wundersch\\u00f6ne Kirche die direkt an den Hausmauern des Vierkanthofes grenzt. \\r\\nEin Festgarten, in dem sich Brautpaare unter dem schattenspendenden Baum das \\u201eJa-Wort\\u201c geben k\\u00f6nnen, \\r\\nein historisches Gew\\u00f6lbe, das 100 Jahre unter der Erde versch\\u00fcttet war und f\\u00fcr intime Trauungen zu zweit wieder freigelegt wurde, \\r\\neine rustikale Scheune als Trauungsort, f\\u00fcr all die, die lockere Boho-Vibes lieben,\\r\\noder die Trauung im Wald f\\u00fcr Naturverbundene, die am liebsten barfu\\u00df den moosbedecken Boden unter ihrem F\\u00fc\\u00dfen sp\\u00fcren.\\r\\nIn diesem herausfordernden Jahr 2020 auch erstmalig unser Festsaal als Trauungsort - nat\\u00fcrlich mit Einhaltung aller zum Zeitpunkt geltenden Regelungen - because love ist not cancelled!\\r\\n\\r\\nSo individuell und vielseitig wie all die Herzen da drau\\u00dfen, das sind wir \\r\\nHuber zu Laah\\r\\n\\u201elet your beautiful soul sparkle and shine\\u201c.\",\"youtube\":\"\",\"copyright\":\"Hannah & Rene, Kati Fine Art\",\"testimonial\":null,\"check\":1,\"ort\":\"Maria Laah, Huber zu Laah\",\"datum\":\"2019_2020\",\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0}}', '2020-11-09 08:56:32', '2020-11-09 08:56:32'),
(1913, 'default', 'updated', 157, 'App\\Project', 437, 'App\\User', '{\"attributes\":{\"user_id\":437,\"name\":\"Huber zu Laah \\u2013 der Hochzeitshof \\u2026 the place where love & magic happens\",\"projektname\":\"1604071674\",\"cat_id\":22,\"cat_name\":\"Location f\\u00fcr Dinner & Tanz\",\"group\":9,\"beschreibung\":\"WOW das ist das h\\u00e4ufigste Wort, dass wir von den G\\u00e4sten h\\u00f6ren, wenn sie unseren Festsaal betreten. Endlos hohe, lichtdurchflutete R\\u00e4ume, Eleganz und Minimalismus, gebrochen mit rustikalen Holzelementen und dekorativen Stoffen, funkelnde Luster und Ambiente-Beleuchtung, trendige Wanddekoration und Kerzenschein \\u2013 all das tr\\u00e4gt dazu bei, unseren Festsaal mit 3-Buchstaben zu kommentieren - WOW! Eintreten und wohlf\\u00fchlen lautet unsere Devise. Unsere Liebe zum Detail bemerkt man, sobald man unseren Hof betritt. Ein W\\u00f6lkchen aus getrockneten Blumen schwebt \\u00fcber unserem gem\\u00fctlichen Samt Sofa im Eingangsbereich, sowie viele weitere liebevolle Details, die sich bis hin zum Wickeltisch ziehen. Auch unser Festsaal ist durchg\\u00e4ngig gro\\u00dfz\\u00fcgig dekoriert, sodass nur noch ein paar Blumen fehlen w\\u00fcrden und schon k\\u00f6nnte man das Fest bei uns feiern. Diese gro\\u00dfz\\u00fcgige \\u201eGrundausstattung\\u201c sch\\u00e4tzen unsere Brautpaare sehr, es spart ihnen viel Zeit und auch Geld. Wer seinen Stil noch mehr zum Ausdruck bringen m\\u00f6chte, kann von unserem Wedding-Styling Angebot Gebrauch machen. Wundersch\\u00f6ne Deko-Elemente wie Glasglocken, Kerzenst\\u00e4nder, Bilderrahmen und vieles mehr bieten wir zum Verleih an. Das ist nicht nur praktisch, sondern auch nachhaltig. Falls erw\\u00fcnscht bieten wir, als ausgebildete Hochzeitsprofis auch Unterst\\u00fctzung bei der Planung an und sorgen auch am Hochzeitstag f\\u00fcr reibungslose Abl\\u00e4ufe. \\r\\n\\r\\nDer \\u201eFirst-Dance\\u201c in unserem Lichterkettenstadel, welcher direkt an den Festsaal grenzt, unter der klitzernden Discokugel, sorgt hier f\\u00fcr das passende Ambiente. \\r\\nAu\\u00dferdem findet man hier eine gem\\u00fctliche Bar, gen\\u00fcgend Sitzm\\u00f6glichkeiten (wenn die Beine eine Pause ben\\u00f6tigen) und eine gro\\u00dfz\\u00fcgige Tanzfl\\u00e4che vor. Auch unser Au\\u00dfenbereich ist besonders an lauen Sommerabenden sehr beliebt und l\\u00e4dt zum Verweilen ein. Ganz neu wird es auf unserem Hochzeitshof eine trendige Dried Flower Bar geben und ein romantisches Dinner for 2 in unserem historischen Gew\\u00f6lbe.\",\"youtube\":\"\",\"copyright\":\"Hannah & Rene, Kati Fine Art\",\"testimonial\":null,\"check\":1,\"ort\":null,\"datum\":null,\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0},\"old\":{\"user_id\":437,\"name\":\"Huber zu Laah \\u2013 der Hochzeitshof \\u2026 the place where love & magic happens\",\"projektname\":\"1604071674\",\"cat_id\":22,\"cat_name\":\"Location f\\u00fcr Dinner & Tanz\",\"group\":9,\"beschreibung\":\"WOW das ist das h\\u00e4ufigste Wort, dass wir von den G\\u00e4sten h\\u00f6ren, wenn sie unseren Festsaal betreten. Endlos hohe, lichtdurchflutete R\\u00e4ume, Eleganz und Minimalismus, gebrochen mit rustikalen Holzelementen und dekorativen Stoffen, funkelnde Luster und Ambiente-Beleuchtung, trendige Wanddekoration und Kerzenschein \\u2013 all das tr\\u00e4gt dazu bei, unseren Festsaal mit 3-Buchstaben zu kommentieren - WOW! Eintreten und wohlf\\u00fchlen lautet unsere Devise. Unsere Liebe zum Detail bemerkt man, sobald man unseren Hof betritt. Ein W\\u00f6lkchen aus getrockneten Blumen schwebt \\u00fcber unserem gem\\u00fctlichen Samt Sofa im Eingangsbereich, sowie viele weitere liebevolle Details, die sich bis hin zum Wickeltisch ziehen. Auch unser Festsaal ist durchg\\u00e4ngig gro\\u00dfz\\u00fcgig dekoriert, sodass nur noch ein paar Blumen fehlen w\\u00fcrden und schon k\\u00f6nnte man das Fest bei uns feiern. Diese gro\\u00dfz\\u00fcgige \\u201eGrundausstattung\\u201c sch\\u00e4tzen unsere Brautpaare sehr, es spart ihnen viel Zeit und auch Geld. Wer seinen Stil noch mehr zum Ausdruck bringen m\\u00f6chte, kann von unserem Wedding-Styling Angebot Gebrauch machen. Wundersch\\u00f6ne Deko-Elemente wie Glasglocken, Kerzenst\\u00e4nder, Bilderrahmen und vieles mehr bieten wir zum Verleih an. Das ist nicht nur praktisch, sondern auch nachhaltig. Falls erw\\u00fcnscht bieten wir, als ausgebildete Hochzeitsprofis auch Unterst\\u00fctzung bei der Planung an und sorgen auch am Hochzeitstag f\\u00fcr reibungslose Abl\\u00e4ufe. Um Hochzeitsg\\u00e4ste zu motivieren auch mit vollgegessenem Magen das Tanzbein zu schwingen, bietet sich unser Discostadel perfekt an, der nur durch einen Zwischengang vom Festsaal getrennt ist. Der \\u201eFist-Dance\\u201c unter der funkelnden Discokugel und vor einem riesigem Lichterketten-Vorhang sorgt hier f\\u00fcr das passende Ambiente. Au\\u00dferdem findet man hier eine gem\\u00fctliche Bar, gen\\u00fcgend Sitzm\\u00f6glichkeiten (wenn die Beine eine Pause ben\\u00f6tigen) und eine gro\\u00dfz\\u00fcgige Tanzfl\\u00e4che vor. Auch unser Au\\u00dfenbereich ist besonders an lauen Sommerabenden sehr beliebt und l\\u00e4dt zum Verweilen ein. Ganz neu wird es auf unserem Hochzeitshof eine trendige Dried Flower Bar geben und ein romantisches Dinner for 2 in unserem historischen Gew\\u00f6lbe.\",\"youtube\":\"\",\"copyright\":\"Hannah & Rene, Kati Fine Art\",\"testimonial\":null,\"check\":1,\"ort\":null,\"datum\":null,\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0}}', '2020-11-09 09:03:33', '2020-11-09 09:03:33'),
(1914, 'default', 'updated', 204, 'App\\Project', 195, 'App\\User', '{\"attributes\":{\"user_id\":195,\"name\":\"Boho Style trifft auf Eleganz\",\"projektname\":\"1604478131\",\"cat_id\":33,\"cat_name\":\"Ausstattung, Dekoartikel & -Verleih | Beste Ausstattung, Dekoartikel & -Verleih\",\"group\":16,\"beschreibung\":\"Die vielf\\u00e4ltige Natur umgeben von prachtvollen Gutsgeb\\u00e4uden bildete im August  2017 eine einzigartige Kulisse f\\u00fcr eine stylisch moderne Boho-Hochzeit in Thon 7, N\\u00e4he Klagenfurt. Auf der gro\\u00dfz\\u00fcgigen Gartenfl\\u00e4che mit Blick auf die Karawanken wurde die Trauung vollzogen. Boho Dekoelemente trafen hier auf extravagante Goldst\\u00fchle, die der Umrahmung der Feierlichkeit eine edle Note einhauchten. \\r\\nDie Hochzeitstafel wurde dann im Inneren des Gutshofes abgehalten - die blauen und goldenen Dekoelemente im geschmackvollen Design unterstrichen das freundliche Ambiente des Festsaales.\",\"youtube\":\"\",\"copyright\":\"Tanja und Josef\",\"testimonial\":null,\"check\":1,\"ort\":null,\"datum\":null,\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0},\"old\":{\"user_id\":195,\"name\":\"Boho-Traumhochzeit mit einzigartigem Ambiente\",\"projektname\":\"1604478131\",\"cat_id\":33,\"cat_name\":\"Ausstattung, Dekoartikel & -Verleih | Beste Ausstattung, Dekoartikel & -Verleih\",\"group\":16,\"beschreibung\":\"Die vielf\\u00e4ltige Natur umgeben von prachtvollen Gutsgeb\\u00e4uden bildete im August  2017 eine einzigartige Kulisse f\\u00fcr eine stylisch moderne Boho-Hochzeit in Thon 7, N\\u00e4he Klagenfurt. Auf der gro\\u00dfz\\u00fcgigen Gartenfl\\u00e4che mit Blick auf die Karawanken wurde die Trauung vollzogen. Boho Dekoelemente trafen hier auf extravagante Goldst\\u00fchle, die der Umrahmung der Feierlichkeit eine edle Note einhauchten. \\r\\nDie Hochzeitstafel wurde dann im Inneren des Gutshofes abgehalten - die blauen und goldenen Dekoelemente im geschmackvollen Design unterstrichen das freundliche Ambiente des Festsaales.\",\"youtube\":\"\",\"copyright\":\"Tanja und Josef\",\"testimonial\":null,\"check\":1,\"ort\":null,\"datum\":null,\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0}}', '2020-11-09 09:26:22', '2020-11-09 09:26:22'),
(1915, 'default', 'updated', 211, 'App\\Project', 195, 'App\\User', '{\"attributes\":{\"user_id\":195,\"name\":\"Prachtvolle Hochzeit am sch\\u00f6nsten See \\u00d6sterreichs\",\"projektname\":\"1604483832\",\"cat_id\":33,\"cat_name\":\"Ausstattung, Dekoartikel & -Verleih | Beste Ausstattung, Dekoartikel & -Verleih\",\"group\":16,\"beschreibung\":\"Im stilvollen Ambiente pr\\u00e4sentiert sich das Seespitzrestaurant in bester Lage am Ufer des W\\u00f6rthersees. Als Teil des Schlosses am W\\u00f6rthersee vereinen sich in dieser Hochzeitslocation moderner Lifestyle mit einer geschichtstr\\u00e4chtigen Story. Der gigantische Blick von der Terrasse auf den W\\u00f6rthersee bot auch im August 2019 einen un\\u00fcbertrefflichen Rahmen bei der von uns ausgestatteten Hochzeitsfeierlichkeit mit internationalen Hochzeitsg\\u00e4sten. \\r\\nIm Au\\u00dfenbereich erstrahlte die impulsante Hochzeitstafel  mit einem Meer aus Blumen in Pastellt\\u00f6nen, umrandet von geschmackvollen Holzst\\u00fchlen.\",\"youtube\":\"\",\"copyright\":\"Sotiris Tsakanikas\",\"testimonial\":null,\"check\":1,\"ort\":null,\"datum\":null,\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0},\"old\":{\"user_id\":195,\"name\":\"Prachtvolle Hochzeit am sch\\u00f6nsten See \\u00d6sterreichs\",\"projektname\":\"1604483832\",\"cat_id\":33,\"cat_name\":\"Ausstattung, Dekoartikel & -Verleih | Beste Ausstattung, Dekoartikel & -Verleih\",\"group\":16,\"beschreibung\":\"Im stilvollen Ambiente pr\\u00e4sentiert sich das Seespitzrestaurant in bester Lage am Ufer des W\\u00f6rthersees. Als Teil des Schlosses am W\\u00f6rthersee vereinen sich in dieser Hochzeitslocation moderner Lifestyle mit einer geschichtstr\\u00e4chtigen Story. Der gigantische Blick von der Terrasse auf den W\\u00f6rthersee bot auch im August 2019 einen un\\u00fcbertrefflichen Rahmen bei der von uns ausgestatteten Hochzeitsfeierlichkeit mit internationalen Hochzeitsg\\u00e4sten. \\r\\nIm Au\\u00dfenbereich erstrahlte die impulsante Hochzeitstafel dekoriert mit einem Meer aus Blumen in Pastellt\\u00f6nen, umrandet von geschmackvollen Holzst\\u00fchlen.\",\"youtube\":\"\",\"copyright\":\"Sotiris Tsakanikas\",\"testimonial\":null,\"check\":1,\"ort\":null,\"datum\":null,\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0}}', '2020-11-09 09:30:08', '2020-11-09 09:30:08'),
