(2197, 'default', 'updated', 244, 'App\\Project', 605, 'App\\User', '{\"attributes\":{\"user_id\":605,\"name\":\"anonym\",\"projektname\":\"1604866670\",\"cat_id\":18,\"cat_name\":\"Fotografie | Soloportrait\",\"group\":6,\"beschreibung\":null,\"youtube\":\"\",\"copyright\":\"manuel tabacchi\",\"testimonial\":null,\"check\":1,\"ort\":\"Fuschl am See\",\"datum\":\"7.9.2019\",\"stat\":1,\"deleted_at\":null,\"extra\":null,\"jury\":0},\"old\":{\"user_id\":605,\"name\":\"anonym\",\"projektname\":\"1604866670\",\"cat_id\":18,\"cat_name\":\"Fotografie | Soloportrait\",\"group\":6,\"beschreibung\":null,\"youtube\":\"\",\"copyright\":\"manuel tabacchi\",\"testimonial\":null,\"check\":1,\"ort\":\"Fuschl am See\",\"datum\":\"7.9.2019\",\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0}}', '2020-11-10 10:40:29', '2020-11-10 10:40:29'),
(2198, 'default', 'updated', 242, 'App\\Project', 605, 'App\\User', '{\"attributes\":{\"user_id\":605,\"name\":\"Burg\",\"projektname\":\"1604865682\",\"cat_id\":18,\"cat_name\":\"Fotografie | Soloportrait\",\"group\":6,\"beschreibung\":null,\"youtube\":\"\",\"copyright\":\"Manuel Tabacchi\",\"testimonial\":null,\"check\":1,\"ort\":\"Eferding\",\"datum\":\"27.9.2018\",\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0},\"old\":{\"user_id\":605,\"name\":\"anonyn\",\"projektname\":\"1604865682\",\"cat_id\":18,\"cat_name\":\"Fotografie | Soloportrait\",\"group\":6,\"beschreibung\":null,\"youtube\":\"\",\"copyright\":\"Manuel Tabacchi\",\"testimonial\":null,\"check\":1,\"ort\":\"Eferding\",\"datum\":\"27.9.2018\",\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0}}', '2020-11-10 10:42:52', '2020-11-10 10:42:52'),
(2199, 'default', 'created', 288, 'App\\Project', 272, 'App\\User', '{\"attributes\":{\"user_id\":272,\"name\":\"Meant to be\",\"projektname\":\"1605005800\",\"cat_id\":24,\"cat_name\":\"Papeterie | Gesamtkonzept\",\"group\":10,\"beschreibung\":\"Die Herausforderung \\u2013 Schaffung eines aussagekr\\u00e4ftigen Gesamtkonzepts, dass das Brautpaar als Mittelpunkt widerspiegelt. Die modern gezeichneten Initialen verk\\u00f6rpern das Brautpaar, kombiniert mit dem designten Herz-&-Zeichen als Symbolik von Verbundenheit und Liebe. Edel und selbstbewusst, geradlinig und stilvoll, gew\\u00fcrzt mit einem Hauch moderner Romantik. Ganz im Gegensatz zum puristisch-stilvollen Design, stehen Umfang und Au\\u00dfergew\\u00f6hnlichkeit der Produkte, aufw\\u00e4ndige Sonder- und Premiumdruckverfahren sowie exklusive Papiere und edle Stoffe. Farben Klassisches Wei\\u00df kombiniert mit der aktuellen und modernen Trendfarbe Ros\\u00e9 als weiche und feminine Komponente. Besonders edel und absolutes Highlight \\u2013 Ros\\u00e9gold im Logo und an den Kanten der Papeterie. Schrift Assemblage, eine Richtung, die schon in der Kunst \\u201eCollagen mit plastischen Objekten\\u201c bedeutet, somit auch perfekt geeignet f\\u00fcr das gew\\u00e4hlte Tiefdruckverfahren der Drucksorten ist und den modernen Charakter unterstreicht und die Tiefe letztendlich gut zur Geltung bringt. Materialien 600g Gmund Cotton, Ros\\u00e9gold, Satin, Samt, Acryl, Ros\\u00e9goldfolien Druck- und Herstellungsverfahren Tiegeldruck, exklusiver Farbschnitt, Hei\\u00dffolienpr\\u00e4gung,\",\"youtube\":\"\",\"copyright\":\"A Twist of Lemon, Markus Schlamadinger und Agentur intern\",\"testimonial\":null,\"check\":1,\"ort\":null,\"datum\":null,\"stat\":0,\"deleted_at\":null,\"extra\":null,\"jury\":0}}', '2020-11-10 10:56:40', '2020-11-10 10:56:40'),
